class SpaceVehicle : public PhysicsBody {
public:
    SpaceVehicle(const Vector3& start_pos, double mass, double velocity)
        : position(start_pos), m(mass), velocity(velocity) {}

    // Calculate force acting on the vehicle from a given body
    double getForceFrom(PhysicsBody* other) const override {
        double distance = (other->position - position).norm();
        return getGravitationalForce(other) * getGravityConstant(distance);
    }

    // Simple thrust (could be advanced with direction/velocity updates)
