class CelestialBody : public PhysicsBody {
public:
    CelestialBody(const Vector3& center, double mass, double radius)
        : position(center), m(mass), radius(radius) {}

    double getGravitationalForce(PhysicsBody* object) const override {
        double distance = (object->position - position).norm();
        if (distance < radius) {
            // Optional: Add rapid falling or tidal effects
            double force = getOrbitalForce(object) * applyRadiusFactor(distance, radius);
            return force;
        }
        // Use standard gravitational formula
        return getGravitationalForce(obj) * getGravityConstant(distance);
    }

    double getOrbitalForce(const SpaceVehicle* obj) const override {
        return constant * obj->m / (distance * distance);
    }
};
```

