    // Calculate gravitational force using inverse cube law
    double gravitationalForce(const CelestialBody& b1, const CelestialBody& b2) const;

    // Calculate total gravitational torque on a body
    double calculateTotalTorque(const CelestialBody& b) const;

    // Run standard integration update (simple Euler, extensible)
    void integrate(double dt);

    // Evaluate orbital stability over given time steps
    bool isStable(double prevPos[], int N) const;

    // Helper: Calculate distance between two bodies
    double calculateDistance(const CelestialBody& b1, const CelestialBody& b2) const;

private:
