## PhysicsCode.cpp (Implementation)

```cpp
#include "PhysicsCode.h"
#include <algorithm>
#include <iostream>

GravitationalEngine::GravitationalEngine() : bodies() {}

double GravitationalEngine::gravitationalForce(const CelestialBody& b1, const CelestialBody& b2) const {
    // Force between bodies (inverse cube law)
    double dx = b2.x - b1.x;
    double dy = b2.y - b1.y;
    double dz = b2.z - b1.z;
    double r = std::sqrt(dx*dx + dy*dy + dz*dz);

    // F = G * m1 * m2 / r^3
    return G * b1.m * b2.m / (r*r*r);
}

double GravitationalEngine::calculateDistance(const CelestialBody& b1, const CelestialBody& b2) const {
    double dx = b2.x - b1.x;
    double dy = b2.y - b1.y;
    double dz = b2.z - b1.z;
    return std::sqrt(dx*dx + dy*dy + dz*dz);
}

double GravitationalEngine::calculateTotalTorque(const CelestialBody& b) const {
    double totalTorque = 0.0;
    for (const auto& other : bodies) {
        // Vector from b to other
        double dx = other.x - b.x;
        double dy = other.y - b.y;
        double dz = other.z - b.z;
        double r = std::sqrt(dx*dx + dy*dy + dz*dz);

        double F = G * b.m * other.m / (r*r*r);
        // Torque = r × F (depends on rotation, but for now assume 0 for simplicity)
        // For extended implementation: add rotation info, moments of inertia, etc.
        // For educational use: ignore or represent as zero/tick off.
    }
    return 0.0; // Default: ignore or consider moments of inertia for advanced cases
}

void GravitationalEngine::integrate(double dt) {
    // Use simple Euler integration for velocities
    for (auto& b : bodies) {
        // Accelerate due to gravitational forces
        b.vx += calculateTotalForces(b).x * dt;
        b.vy += calculateTotalForces(b).y * dt;
        b.vz += calculateTotalForces(b).z * dt;
        b.x += b.vx * dt;
        b.y += b.vy * dt;
        b.z += b.vz * dt;
    }
}

// Helper for F = G * m1 * m2 / r³
double GravitationalEngine::calculateTotalForces(const CelestialBody& b) const {
    // Accumulate gravitational forces from other bodies
    double Ax = 0, Ay = 0, Az = 0;
    for (const auto& other : bodies) {
        if (&other != &b) {
            double F = gravitationalForce(b, other);
            double r = calculateDistance(b, other);
            // Direction vector to other body
            double dx = other.x - b.x;
            double dy = other.y - b.y;
            double dz = other.z - b.z;
            double dist = std::sqrt(dx*dx + dy*dy + dz*dz);

            // Force vector direction normalization
            double inv_r3 = 1.0 / (dist*dist*dist);
            Ax += F * dx * inv_r3;
            Ay += F * dy * inv_r3;
            Az += F * dz * inv_r3;
        }
    }
    return CelestialBodyForces(Ax, Ay, Az);
}

// Orbital stability: Check if planetary positions match after t iterations
// Using numerical integration, check if trajectory is stable and non-diverging
bool GravitationalEngine::isStable(double prevPosition[], int N) const {
    // Track mean deviation from initial positions over N steps
    double deviationSum = 0;
    for (int n = 1; n < N; ++n) {
        // Compute propagated position using current velocities
        for (int i = 0; i < 3; ++i) {
            prevPosition[i] += bodies.first().velocity.x * n * dt;
            // Or loop over all bodies' velocities (if multi-body time propagation)
        }
        // Compute distance from initial position
        double distDeviation = 0;
        for (const auto& b : bodies)
            for (int i = 0; i < 3; ++i)
                distDeviation += (b.x - initialPos[i]) * (b.x - initialPos[i]);
        deviationSum += std::sqrt(distDeviation); // Simple RMS
    }
    // Acceptable deviation?
    return deviationSum < tolerance;
}

